#include <vector>
#include <queue>

class Solution {
public:
    int countIslands(std::vector<std::vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));

        auto bfs = [&](int sr, int sc) {
            std::queue<std::pair<int, int>> qu;
            qu.push({sr, sc});
            visited[sr][sc] = true;
            long long total = 0;

            int dr[] = {-1, 1, 0, 0};
            int dc[] = {0, 0, -1, 1};

            while (!qu.empty()) {
                auto [r, c] = qu.front();
                qu.pop();
                total += grid[r][c];

                for (int i = 0; i < 4; ++i) {
                    int nr = r + dr[i], nc = c + dc[i];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && grid[nr][nc] > 0) {
                        visited[nr][nc] = true;
                        qu.push({nr, nc});
                    }
                }
            }
            return total;
        };

        int ans = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] > 0 && !visited[r][c]) {
                    if (bfs(r, c) % k == 0) ans++;
                }
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int countIslands(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        int ans = 0;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] > 0 && !visited[r][c]) {
                    Queue<int[]> queue = new ArrayDeque<>();
                    queue.add(new int[]{r, c});
                    visited[r][c] = true;
                    long total = 0;

                    while (!queue.isEmpty()) {
                        int[] cell = queue.poll();
                        int cr = cell[0], cc = cell[1];
                        total += grid[cr][cc];

                        for (int i = 0; i < 4; i++) {
                            int nr = cr + dr[i], nc = cc + dc[i];
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && grid[nr][nc] > 0) {
                                visited[nr][nc] = true;
                                queue.add(new int[]{nr, nc});
                            }
                        }
                    }

                    if (total % k == 0) ans++;
                }
            }
        }

        return ans;
    }
}

