var countIslands = function(grid, k) {
    const m = grid.length, n = grid[0].length;
    const visited = Array.from({ length: m }, () => new Uint8Array(n));
    let ans = 0;

    const dr = [-1, 1, 0, 0];
    const dc = [0, 0, -1, 1];

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] > 0 && !visited[r][c]) {
                const queue = [[r, c]];
                visited[r][c] = 1;
                let total = 0;

                let head = 0;
                while (head < queue.length) {
                    const [cr, cc] = queue[head++];
                    total += grid[cr][cc];

                    for (let i = 0; i < 4; i++) {
                        const nr = cr + dr[i], nc = cc + dc[i];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && grid[nr][nc] > 0) {
                            visited[nr][nc] = 1;
                            queue.push([nr, nc]);
                        }
                    }
                }

                if (total % k === 0) ans++;
            }
        }
    }

    return ans;
};
